const fs=require("fs");
const css=fs.readFileSync("/tmp/opencode/fonts.css","utf8");
const blocks=css.split("@font-face").slice(1);
const out=[];
for(const b of blocks){
  if(!/unicode-range: U\+0000-00FF/.test(b)) continue;
  const fam=b.match(/font-family: '\''([^'\'']+)'\''/)[1];
  const style=b.match(/font-style: ([^;]+)/)[1].trim();
  const weight=b.match(/font-weight: ([^;]+)/)[1].trim();
  const url=b.match(/url\((https:[^)]+)\)/)[1];
  const name=fam.toLowerCase().replace(/ /g,"-")+"-"+weight+(style==="italic"?"i":"")+".woff2";
  out.push({fam,style,weight,url,name});
}
console.log(JSON.stringify(out,null,1));
fs.writeFileSync("/tmp/opencode/fontlist.json",JSON.stringify(out));
