/* ═══════════════════════════════════════════════════════════
   MAP · HTML NODE LAYER
   ═══════════════════════════════════════════════════════════ */
.map-nodes,
.map-tokens {
  position: absolute;
  inset: 0;
  pointer-events: none;
}
.map-nodes { z-index: 3; }
.map-tokens { z-index: 5; }

.prov {
  --ring-size: 35px;
  --hit-size: 44px;
  position: absolute;
  width: var(--hit-size);
  height: var(--hit-size);
  transform: translate(-50%, -50%);
  display: grid;
  place-items: center;
  border: 0;
  border-radius: 50%;
  background: none;
  padding: 0;
  pointer-events: auto;
  color: var(--neutral);
  -webkit-tap-highlight-color: transparent;
}
.prov__halo {
  position: absolute;
  left: 50%;
  top: 50%;
  width: calc(var(--ring-size) * 2.2);
  height: calc(var(--ring-size) * 2.2);
  transform: translate(-50%, -50%);
  border-radius: 50%;
  background: currentColor;
  opacity: 0.12;
  filter: blur(9px);
  transition: opacity 0.35s, transform 0.35s;
}
.prov__pulse {
  position: absolute;
  left: 50%;
  top: 50%;
  width: calc(var(--ring-size) + 16px);
  height: calc(var(--ring-size) + 16px);
  transform: translate(-50%, -50%);
  border: 1px solid currentColor;
  border-radius: 50%;
  opacity: 0;
  pointer-events: none;
}
.prov__ring {
  position: relative;
  width: var(--ring-size);
  height: var(--ring-size);
  display: grid;
  place-items: center;
  border: 1px solid currentColor;
  border-radius: 50%;
  background:
    radial-gradient(circle at 38% 30%, rgba(255, 255, 255, 0.12), transparent 55%),
    #0b1020;
  box-shadow: 0 3px 14px rgba(0, 0, 0, 0.6), inset 0 0 12px rgba(0, 0, 0, 0.55);
  transition: border-color 0.3s, box-shadow 0.3s, transform 0.3s, background 0.3s;
}
.prov__ring::after {
  content: '';
  position: absolute;
  inset: 5px;
  border: 1px solid currentColor;
  border-radius: 50%;
  opacity: 0.25;
}
.prov__glyph {
  font-size: 14px;
  line-height: 1;
  color: currentColor;
  opacity: 0.9;
  transition: color 0.3s, text-shadow 0.3s;
}
.prov__label {
  position: absolute;
  top: calc(50% + var(--ring-size) / 2 + 3px);
  left: 50%;
  transform: translateX(-50%);
  max-width: 128px;
  white-space: nowrap;
  font-family: var(--serif);
  font-size: 9.5px;
  font-weight: 500;
  letter-spacing: 0.12em;
  text-transform: uppercase;
  color: #aeb1c0;
  text-shadow: 0 1px 3px #05070d, 0 0 6px #05070d, 0 0 12px #05070d;
  pointer-events: none;
  transition: color 0.3s;
}
.prov__badge {
  position: absolute;
  left: calc(50% + var(--ring-size) * 0.36);
  top: calc(50% - var(--ring-size) * 0.66);
  min-width: 16px;
  height: 15px;
  padding: 0 4px;
  display: grid;
  place-items: center;
  border: 1px solid rgba(255, 255, 255, 0.22);
  border-radius: 8px;
  background: #090c16;
  font-family: var(--serif);
  font-size: 8px;
  font-weight: 600;
  line-height: 1;
  color: #d8dae3;
  box-shadow: 0 2px 8px rgba(0, 0, 0, 0.5);
  pointer-events: none;
  transition: border-color 0.3s, color 0.3s;
}
.prov__crown {
  position: absolute;
  left: 50%;
  top: calc(50% - var(--ring-size) * 0.5 - 19px);
  transform: translateX(-50%);
  width: 13px;
  height: 13px;
  color: var(--gold);
  opacity: 0.95;
  filter: drop-shadow(0 0 5px rgba(232, 199, 122, 0.7));
  pointer-events: none;
}
.prov__crown svg { width: 100%; height: 100%; display: block; }

.prov.is-neutral { color: rgba(168, 173, 192, 0.75); }
.prov.is-neutral .prov__label { color: #9a9eb0; }
.prov.is-player { color: var(--player); }
.prov.is-player .prov__ring {
  background:
    radial-gradient(circle at 40% 30%, rgba(255, 238, 190, 0.22), transparent 60%),
    #17130b;
  box-shadow: 0 0 16px rgba(242, 212, 140, 0.18), 0 3px 14px rgba(0, 0, 0, 0.6), inset 0 0 12px rgba(232, 199, 122, 0.08);
}
.prov.is-player .prov__label { color: #dcc99d; }
.prov.is-player .prov__glyph { color: var(--gold-bright); text-shadow: 0 0 8px rgba(255, 225, 155, 0.6); }
.prov.is-player .prov__badge { border-color: rgba(242, 212, 140, 0.5); color: #f0e0b6; }
.prov.is-player .prov__halo { opacity: 0.16; }
.prov.is-enemy { color: var(--enemy); }
.prov.is-enemy .prov__ring {
  background:
    radial-gradient(circle at 40% 30%, rgba(220, 160, 245, 0.18), transparent 60%),
    #140d1c;
  box-shadow: 0 0 18px rgba(196, 123, 224, 0.2), 0 3px 14px rgba(0, 0, 0, 0.6), inset 0 0 12px rgba(150, 80, 190, 0.1);
}
.prov.is-enemy .prov__label { color: #c6aed2; }
.prov.is-enemy .prov__glyph { color: #dfb2f2; text-shadow: 0 0 8px rgba(190, 120, 220, 0.6); }
.prov.is-enemy .prov__badge { border-color: rgba(196, 123, 224, 0.5); color: #e3c2ee; }
.prov.is-enemy .prov__halo { opacity: 0.18; }
.prov:hover .prov__ring,
.prov:focus-visible .prov__ring {
  border-color: var(--gold-bright);
  box-shadow: 0 0 22px rgba(255, 225, 155, 0.35), 0 3px 14px rgba(0, 0, 0, 0.6);
  transform: scale(1.07);
}
.prov:hover .prov__halo,
.prov:focus-visible .prov__halo { opacity: 0.32; transform: translate(-50%, -50%) scale(1.15); }
.prov:focus-visible { outline: none; }
.prov:focus-visible .prov__ring { outline: 1px solid var(--gold); outline-offset: 4px; }
.prov.is-selected .prov__ring {
  border-color: var(--gold-bright);
  border-width: 2px;
  box-shadow: 0 0 26px rgba(255, 225, 155, 0.55), 0 3px 16px rgba(0, 0, 0, 0.65);
  transform: scale(1.1);
}
.prov.is-selected .prov__halo { opacity: 0.42; transform: translate(-50%, -50%) scale(1.25); }
.prov.is-selected .prov__label { color: #fff2cf; }
.prov.is-adjacent .prov__pulse {
  opacity: 0.35;
  border-style: dashed;
  animation: provRing 2.4s ease-out infinite;
}
.prov.is-targetable .prov__pulse {
  opacity: 0.6;
  border-color: var(--gold-bright);
  animation: targetPulseHTML 1.8s ease-out infinite;
}
.prov.is-targetable .prov__ring { border-color: var(--gold-bright); box-shadow: 0 0 20px rgba(255, 225, 155, 0.4); }
.prov.is-targetable .prov__label { color: var(--gold-bright); }
.prov.is-capture .prov__ring { animation: captureRingHTML 1s ease; }
.prov.is-smited .prov__ring { animation: smiteShakeHTML 0.55s ease; }
.prov.is-smited::after {
  content: '✦';
  position: absolute;
  left: 50%;
  top: 50%;
  transform: translate(-50%, -50%);
  color: #fff2cf;
  font-size: 30px;
  text-shadow: 0 0 20px #ffe9b0, 0 0 40px #ffcf6e;
  animation: smiteBurst 0.7s ease-out forwards;
  pointer-events: none;
}
@keyframes provRing {
  0% { transform: translate(-50%, -50%) scale(0.85); opacity: 0.45; }
  80% { transform: translate(-50%, -50%) scale(1.3); opacity: 0; }
  100% { opacity: 0; }
}
@keyframes targetPulseHTML {
  0% { transform: translate(-50%, -50%) scale(0.8); opacity: 0.8; }
  75% { transform: translate(-50%, -50%) scale(1.45); opacity: 0; }
  100% { opacity: 0; }
}
@keyframes captureRingHTML {
  0% { box-shadow: 0 0 40px 14px rgba(255, 230, 170, 0.8); transform: scale(1.25); }
  100% { box-shadow: 0 0 16px rgba(242, 212, 140, 0.2); transform: scale(1); }
}
@keyframes smiteShakeHTML {
  0%, 100% { transform: translate(0, 0); }
  25% { transform: translate(-4px, 2px); }
  50% { transform: translate(4px, -2px); }
  75% { transform: translate(-2px, 1px); }
}
@keyframes smiteBurst {
  0% { opacity: 0; transform: translate(-50%, -50%) scale(0.4); }
  30% { opacity: 1; transform: translate(-50%, -50%) scale(1.3); }
  100% { opacity: 0; transform: translate(-50%, -50%) scale(2.1); }
}

.map-tokens .token {
  --token-size: 29px;
  position: absolute;
  width: 0;
  height: 0;
  z-index: 2;
  transition: left 0.55s cubic-bezier(0.22, 0.8, 0.25, 1), top 0.55s cubic-bezier(0.22, 0.8, 0.25, 1);
}
.token__disc {
  position: absolute;
  left: 50%;
  top: 50%;
  width: var(--token-size);
  height: var(--token-size);
  transform: translate(-50%, -50%);
  display: grid;
  place-items: center;
  border-radius: 50%;
  font-size: 13px;
  line-height: 1;
}
.token__halo {
  position: absolute;
  left: 50%;
  top: 50%;
  width: calc(var(--token-size) * 2.1);
  height: calc(var(--token-size) * 2.1);
  transform: translate(-50%, -50%);
  border-radius: 50%;
  filter: blur(10px);
  opacity: 0.45;
}
.token__ring {
  position: absolute;
  left: 50%;
  top: 50%;
  width: calc(var(--token-size) + 10px);
  height: calc(var(--token-size) + 10px);
  transform: translate(-50%, -50%);
  border: 1px solid currentColor;
  border-radius: 50%;
  opacity: 0.5;
  animation: tokenRingHTML 3s ease-out infinite;
}
.token__count {
  position: absolute;
  left: calc(50% + 8px);
  top: calc(50% - 19px);
  min-width: 17px;
  height: 16px;
  padding: 0 4px;
  display: grid;
  place-items: center;
  border-radius: 8px;
  border: 1px solid currentColor;
  background: #080b14;
  font-family: var(--serif);
  font-size: 8.5px;
  font-weight: 700;
  line-height: 1;
  color: #f2e8d2;
  box-shadow: 0 2px 8px rgba(0, 0, 0, 0.6);
  z-index: 2;
}
.token--player { color: #f7de9d; }
.token--player .token__disc {
  color: #1d1709;
  background: radial-gradient(circle at 38% 28%, #fff5d2, #f0d190 45%, #b98f45 100%);
  border: 1px solid #fff0c4;
  box-shadow: 0 0 20px rgba(255, 220, 140, 0.65), 0 2px 8px rgba(0, 0, 0, 0.6);
}
.token--player .token__halo { background: #ffe2a0; }
.token--enemy { color: #c47be0; }
.token--enemy .token__disc {
  color: #f0d0ff;
  background: radial-gradient(circle at 38% 28%, #3a2048, #1c1026 55%, #0d0714 100%);
  border: 1px solid #c47be0;
  box-shadow: 0 0 20px rgba(180, 100, 220, 0.55), 0 2px 8px rgba(0, 0, 0, 0.6);
}
.token--enemy .token__halo { background: #b466d8; }
.token--player .token__count { border-color: rgba(255, 233, 176, 0.6); }
.token--enemy .token__count { border-color: rgba(196, 123, 224, 0.6); }
.token.is-hidden { display: none; }
@keyframes tokenRingHTML {
  0% { transform: translate(-50%, -50%) scale(0.9); opacity: 0.55; }
  70% { transform: translate(-50%, -50%) scale(1.35); opacity: 0; }
  100% { opacity: 0; }
}
.map-stage.is-targeting .prov:not(.is-targetable) { opacity: 0.45; }
.map-stage.is-targeting .prov:not(.is-targetable):hover { opacity: 0.8; }
.prov.is-host-hidden .prov__glyph { opacity: 0; }
.road.is-targetable { stroke: rgba(232, 199, 122, 0.7); stroke-width: 2; }

