/* ═══════════════════════════════════════════════════════════
   Realm map renderer
   ═══════════════════════════════════════════════════════════ */
(function () {
  'use strict';
  const { PROVINCES, EDGES, GLYPHS } = window.GATC_DATA;

  const OWNER_LABEL = { player: 'Dawn', enemy: 'Hollow', neutral: 'Free' };

  // deterministic pseudo random for stars
  function mulberry(seed) {
    return function () {
      seed |= 0; seed = (seed + 0x6D2B79F5) | 0;
      let t = Math.imul(seed ^ (seed >>> 15), 1 | seed);
      t = (t + Math.imul(t ^ (t >>> 7), 61 | t)) ^ t;
      return ((t ^ (t >>> 14)) >>> 0) / 4294967296;
    };
  }

  function mountain(x, y, s, stroke) {
    return `<path class="mount" d="M ${x - 12 * s} ${y + 7 * s} L ${x} ${y - 11 * s} L ${x + 12 * s} ${y + 7 * s}" fill="rgba(255,255,255,.025)" stroke="${stroke}" stroke-width="1.1" stroke-linejoin="round"/>
      <path d="M ${x - 4 * s} ${y - 3 * s} L ${x} ${y - 11 * s} L ${x + 4 * s} ${y - 3 * s}" fill="none" stroke="rgba(255,255,255,.08)" stroke-width=".8"/>`;
  }
  function tree(x, y, s, stroke) {
    return `<g stroke="${stroke}" stroke-width="1" fill="rgba(255,255,255,.025)">
      <path d="M ${x} ${y + 8 * s} v ${-6 * s}"/>
      <path d="M ${x - 5 * s} ${y + 3 * s} L ${x} ${y - 8 * s} L ${x + 5 * s} ${y + 3 * s}Z"/>
      <path d="M ${x - 3.6 * s} ${y - 1 * s} L ${x} ${y - 10 * s} L ${x + 3.6 * s} ${y - 1 * s}Z" fill="none"/>
    </g>`;
  }
  function waves(x, y, s, stroke) {
    return `<g stroke="${stroke}" stroke-width="1" fill="none" opacity=".8">
      <path d="M ${x - 12 * s} ${y} q ${4 * s} ${-3 * s} ${8 * s} 0 t ${8 * s} 0 t ${8 * s} 0"/>
      <path d="M ${x - 7 * s} ${y + 6 * s} q ${4 * s} ${-3 * s} ${8 * s} 0 t ${8 * s} 0" opacity=".6"/>
    </g>`;
  }

  class MapView {
    constructor({ svg, nodes, tokens, stage, onSelect, onHover, onLeave }) {
      this.svg = svg;
      this.nodesEl = nodes;
      this.tokensEl = tokens;
      this.stage = stage;
      this.onSelect = onSelect;
      this.onHover = onHover;
      this.onLeave = onLeave;
      this.nodeEls = new Map();
      this.roadEls = [];
      this.tokens = {};
      this._build();
    }

    _build() {
      const rand = mulberry(9182);
      let stars = '';
      for (let i = 0; i < 96; i++) {
        const x = (rand() * 1000).toFixed(1);
        const y = (rand() * 700).toFixed(1);
        const r = (rand() * 1.1 + 0.2).toFixed(2);
        const o = (rand() * 0.5 + 0.12).toFixed(2);
        stars += `<circle cx="${x}" cy="${y}" r="${r}" fill="#f7ebcf" opacity="${o}"/>`;
      }

      const island = 'M 62,424 C 42,360 72,300 132,270 C 172,240 192,200 244,184 C 304,164 332,120 404,115 C 470,110 500,70 572,72 C 642,74 672,100 742,95 C 812,90 862,120 902,165 C 937,210 952,270 932,330 C 917,385 952,440 926,500 C 901,565 852,600 802,620 C 742,646 692,690 612,690 C 542,690 500,665 440,670 C 380,675 335,700 275,690 C 210,680 180,630 152,595 C 112,550 78,500 62,424 Z';

      // decorative land details
      let decor = '';
      decor += mountain(350, 188, 1.15, 'rgba(190,180,158,.3)') + mountain(430, 170, 0.9, 'rgba(190,180,158,.24)') + mountain(376, 142, 0.7, 'rgba(190,180,158,.2)');
      decor += mountain(786, 292, 1.05, 'rgba(190,180,158,.26)') + mountain(868, 264, 0.8, 'rgba(190,180,158,.2)');
      decor += mountain(628, 88, 0.8, 'rgba(190,180,158,.2)') + mountain(522, 96, 0.65, 'rgba(190,180,158,.16)');
      decor += tree(204, 382, 1.15, 'rgba(170,190,170,.25)') + tree(168, 340, 0.9, 'rgba(170,190,170,.2)') + tree(290, 398, 0.8, 'rgba(170,190,170,.2)') + tree(206, 286, 0.7, 'rgba(170,190,170,.16)');
      decor += tree(500, 606, 0.95, 'rgba(170,190,170,.22)') + tree(586, 608, 0.75, 'rgba(170,190,170,.18)') + tree(440, 688, 0.65, 'rgba(170,190,170,.16)');
      decor += waves(318, 516, 1, 'rgba(150,180,220,.2)') + waves(414, 438, 0.8, 'rgba(150,180,220,.16)') + waves(882, 210, 0.75, 'rgba(150,180,220,.15)');
      // river
      decor += `<path d="M 414 250 C 448 310 340 366 362 458 C 380 530 438 588 470 630" fill="none" stroke="rgba(130,160,210,.12)" stroke-width="2.4"/>`;
      // citadel spires behind the capital
      decor += `<g stroke="rgba(196,123,224,.28)" fill="rgba(196,123,224,.05)" stroke-width="1">
        <path d="M 848 552 L 858 500 L 868 552Z"/><path d="M 866 552 L 880 486 L 894 552Z"/><path d="M 890 552 L 902 512 L 914 552Z"/>
        <path d="M 840 552 h 82" stroke-width="1.4"/>
      </g>`;
      // ashen obelisks
      decor += `<g stroke="rgba(190,180,158,.2)" fill="rgba(190,180,158,.04)" stroke-width="1">
        <path d="M 660 462 l 4 -20 l 4 20Z"/><path d="M 736 470 l 3 -15 l 3 15Z"/><path d="M 682 480 l 2 -11 l 2 11Z"/>
      </g>`;
      // ruins at gate
      decor += `<g stroke="rgba(190,180,158,.18)" fill="none" stroke-width="1">
        <path d="M 486 386 v -18 M 482 372 h 8 M 530 382 v -13 M 527 372 h 6"/>
      </g>`;
      // sea compass
      decor += `<g class="map-compass" transform="translate(86,134)">
        <circle r="31" stroke="rgba(232,199,122,.17)" fill="none"/>
        <circle r="24" stroke="rgba(232,199,122,.1)" fill="none"/>
        <path d="M 0 -30 L 5 -6 L 0 0 L -5 -6Z" fill="rgba(232,199,122,.4)" stroke="none"/>
        <path d="M 0 30 L 5 6 L 0 0 L -5 6Z" fill="rgba(232,199,122,.16)" stroke="none"/>
        <path d="M -30 0 L -6 5 L 0 0 L -6 -5Z" fill="rgba(232,199,122,.16)" stroke="none"/>
        <path d="M 30 0 L 6 5 L 0 0 L 6 -5Z" fill="rgba(232,199,122,.22)" stroke="none"/>
        <text x="0" y="-35" text-anchor="middle" font-family="Cinzel, serif" font-size="8" letter-spacing="2" fill="rgba(232,199,122,.4)">N</text>
      </g>`;
      decor += `<text x="88" y="205" class="map-label-deco" transform="rotate(-90 88 205)" letter-spacing="3.2">THE SUNLESS SEA</text>`;
      decor += `<text x="500" y="668" text-anchor="middle" font-family="Cinzel, serif" font-size="22" letter-spacing="11" fill="rgba(232,199,122,.07)">AETHERMOOR</text>`;

      // roads
      let roads = '';
      EDGES.forEach(([a, b], i) => {
        const p1 = PROVINCES[a], p2 = PROVINCES[b];
        const mx = (p1.x + p2.x) / 2, my = (p1.y + p2.y) / 2;
        const dx = p2.x - p1.x, dy = p2.y - p1.y;
        const len = Math.hypot(dx, dy) || 1;
        const bend = [-16, 12, -9, 18, -13, 8][i % 6];
        const cx = mx + (-dy / len) * bend;
        const cy = my + (dx / len) * bend;
        roads += `<path class="road" data-a="${a}" data-b="${b}" d="M ${p1.x} ${p1.y} Q ${cx.toFixed(1)} ${cy.toFixed(1)} ${p2.x} ${p2.y}"/>`;
      });

      this.svg.innerHTML = `
        <defs>
          <radialGradient id="seaGlow" cx="50%" cy="46%" r="62%">
            <stop offset="0%" stop-color="#16203a"/>
            <stop offset="55%" stop-color="#0c1222"/>
            <stop offset="100%" stop-color="#070a12"/>
          </radialGradient>
          <linearGradient id="landGrad" x1="20%" y1="0%" x2="80%" y2="100%">
            <stop offset="0%" stop-color="#1a2132"/>
            <stop offset="42%" stop-color="#131a29"/>
            <stop offset="100%" stop-color="#0c111d"/>
          </linearGradient>
          <radialGradient id="landLight" cx="42%" cy="34%" r="55%">
            <stop offset="0%" stop-color="rgba(232,199,122,.09)"/>
            <stop offset="70%" stop-color="rgba(232,199,122,.015)"/>
            <stop offset="100%" stop-color="rgba(232,199,122,0)"/>
          </radialGradient>
          <filter id="softShadow" x="-20%" y="-20%" width="140%" height="140%">
            <feDropShadow dx="0" dy="10" stdDeviation="14" flood-color="#000" flood-opacity=".55"/>
          </filter>
          <filter id="nodeBlur"><feGaussianBlur stdDeviation="4"/></filter>
        </defs>
        <rect width="1000" height="700" fill="url(#seaGlow)"/>
        <g>${stars}</g>
        <g class="sea-rings">
          <circle cx="500" cy="350" r="330"/><circle cx="500" cy="350" r="420"/>
          <circle cx="500" cy="350" r="510"/>
        </g>
        <g class="sea-grid">
          <path d="M0 175 H1000 M0 350 H1000 M0 525 H1000 M250 0 V700 M500 0 V700 M750 0 V700" stroke-dasharray="1 12"/>
        </g>
        <path class="land-coast" d="${island}" transform="translate(7,9) scale(.985)"/>
        <path class="land-shape" d="${island}"/>
        <path d="${island}" fill="url(#landLight)"/>
        <g opacity=".9">${decor}</g>
        <g>${roads}</g>
      `;

      this.roadEls = Array.from(this.svg.querySelectorAll('.road'));

      // build HTML provinces
      PROVINCES_LIST().forEach(p => {
        const btn = document.createElement('button');
        btn.type = 'button';
        btn.className = 'prov is-neutral';
        btn.dataset.id = p.id;
        btn.style.left = (p.x / 10) + '%';
        btn.style.top = (p.y / 7) + '%';
        btn.setAttribute('aria-label', p.name);
        btn.innerHTML = `
          <span class="prov__halo" aria-hidden="true"></span>
          <span class="prov__pulse" aria-hidden="true"></span>
          <span class="prov__ring" aria-hidden="true"><span class="prov__glyph">${GLYPHS[p.type] || '✦'}</span></span>
          <span class="prov__badge" aria-hidden="true">0</span>
          <span class="prov__label">${p.name}</span>
          ${p.capital ? '<span class="prov__crown" aria-hidden="true"><svg><use href="#i-crown"/></svg></span>' : ''}
        `;
        btn.addEventListener('click', () => this.onSelect(p.id));
        btn.addEventListener('mouseenter', e => this.onHover && this.onHover(p.id, e));
        btn.addEventListener('mousemove', e => this.onHover && this.onHover(p.id, e));
        btn.addEventListener('mouseleave', () => this.onLeave && this.onLeave());
        btn.addEventListener('focus', e => this.onHover && this.onHover(p.id, e));
        btn.addEventListener('blur', () => this.onLeave && this.onLeave());
        this.nodesEl.appendChild(btn);
        this.nodeEls.set(p.id, btn);
      });

      // host tokens
      this.tokens.player = this._makeToken('player', '✦');
      this.tokens.enemy = this._makeToken('enemy', '◈');
    }

    _makeToken(side, glyph) {
      const el = document.createElement('div');
      el.className = 'token token--' + side;
      el.dataset.side = side;
      el.innerHTML = `
        <span class="token__halo" aria-hidden="true"></span>
        <span class="token__ring" aria-hidden="true"></span>
        <span class="token__disc" aria-hidden="true">${glyph}</span>
        <span class="token__count">0</span>
      `;
      this.tokensEl.appendChild(el);
      return el;
    }

    update(state, view = {}) {
      const playerPos = state.playerPos;
      const selected = view.selected || null;
      const targetable = view.targetable || new Set();
      const hostProvince = selected;

      PROVINCES_LIST().forEach(p => {
        const el = this.nodeEls.get(p.id);
        if (!el) return;
        const owner = state.owners[p.id] || 'neutral';
        const garrison = state.garrisons[p.id] ?? 0;
        el.classList.remove('is-player', 'is-enemy', 'is-neutral', 'is-selected', 'is-adjacent', 'is-targetable', 'is-host-hidden');
        el.classList.add('is-' + owner);
        el.classList.toggle('is-selected', selected === p.id);
        el.classList.toggle('is-adjacent', p.id !== playerPos && p.neighbors.includes(playerPos));
        el.classList.toggle('is-targetable', targetable.has(p.id));
        el.classList.toggle('is-host-hidden', state.playerPos === p.id || state.enemyPos === p.id);
        const badge = el.querySelector('.prov__badge');
        if (badge) badge.textContent = garrison;
        el.setAttribute('aria-label', `${p.name}, ${OWNER_LABEL[owner]}, garrison ${garrison}${state.playerPos === p.id ? ', your host is here' : ''}`);
        el.setAttribute('aria-pressed', selected === p.id ? 'true' : 'false');
        el.classList.toggle('is-capital', Boolean(p.capital));
      });

      for (const road of this.roadEls) {
        road.classList.toggle('is-adjacent', road.dataset.a === playerPos || road.dataset.b === playerPos);
      }

      this._placeToken('player', state.playerPos, state.host);
      this._placeToken('enemy', state.enemyPos, getEnemyHost(state));
      this.stage.classList.toggle('is-targeting', Boolean(view.targeting));
    }

    _placeToken(side, provinceId, count) {
      const p = PROVINCES[provinceId];
      const el = this.tokens[side];
      if (!p || !el) return;
      el.style.left = (p.x / 10) + '%';
      el.style.top = (p.y / 7) + '%';
      const badge = el.querySelector('.token__count');
      if (badge) badge.textContent = count;
      el.classList.toggle('is-hidden', !provinceId);
    }

    flashProvince(id, kind = 'capture') {
      const el = this.nodeEls.get(id);
      if (!el) return;
      const cls = kind === 'smite' ? 'is-smited' : 'is-capture';
      el.classList.remove(cls);
      // force reflow so the animation can replay
      void el.offsetWidth;
      el.classList.add(cls);
      setTimeout(() => el.classList.remove(cls), 1100);
    }

    shake() {
      if (!this.stage) return;
      this.stage.classList.remove('is-shaking');
      void this.stage.offsetWidth;
      this.stage.classList.add('is-shaking');
      setTimeout(() => this.stage.classList.remove('is-shaking'), 500);
    }

    glow() {
      if (!this.stage) return;
      this.stage.classList.remove('is-breakthrough');
      void this.stage.offsetWidth;
      this.stage.classList.add('is-breakthrough');
      setTimeout(() => this.stage.classList.remove('is-breakthrough'), 1200);
    }
  }

  function PROVINCES_LIST() {
    return Object.values(PROVINCES);
  }
  function getEnemyHost(state) {
    return state.enemyHost != null ? state.enemyHost : (state.enemyHost = 9);
  }

  window.GATC_MAP = { MapView };
})();

/* ═══════════════════════════════════════════════════════════
   Sound — a small generative score, no external audio files
   ═══════════════════════════════════════════════════════════ */
(function () {
  'use strict';

  const SCALE = [146.83, 174.61, 196.0, 220.0, 261.63, 293.66, 349.23, 392.0, 440.0, 523.25];

  class SoundEngine {
    constructor(options = {}) {
      this.ctx = null;
      this.master = null;
      this.musicBus = null;
      this.sfxBus = null;
      this.delay = null;
      this.musicVolume = (options.music ?? 55) / 100;
      this.sfxVolume = (options.sfx ?? 70) / 100;
      this.muted = Boolean(options.muted);
      this.started = false;
      this.bellTimer = null;
      this.bellStep = 0;
      this.droneNodes = [];
    }

    init() {
      if (this.ctx) {
        if (this.ctx.state === 'suspended') this.ctx.resume();
        return;
      }
      const Ctx = window.AudioContext || window.webkitAudioContext;
      if (!Ctx) return;
      this.ctx = new Ctx();
      this.master = this.ctx.createGain();
      this.master.gain.value = this.muted ? 0 : 0.85;
      this.master.connect(this.ctx.destination);

      this.musicBus = this.ctx.createGain();
      this.musicBus.gain.value = this.musicVolume * 0.3;
      this.musicBus.connect(this.master);

      this.sfxBus = this.ctx.createGain();
      this.sfxBus.gain.value = this.sfxVolume * 0.55;
      this.sfxBus.connect(this.master);

      // shared echo for bells
      this.delay = this.ctx.createDelay(2.5);
      this.delay.delayTime.value = 0.42;
      const feedback = this.ctx.createGain();
      feedback.gain.value = 0.33;
      const wet = this.ctx.createGain();
      wet.gain.value = 0.35;
      this.delay.connect(feedback);
      feedback.connect(this.delay);
      this.delay.connect(wet);
      wet.connect(this.musicBus);

      this._startScore();
      this.started = true;
    }

    _startScore() {
      const ctx = this.ctx;
      if (!ctx) return;
      const filter = ctx.createBiquadFilter();
      filter.type = 'lowpass';
      filter.frequency.value = 320;
      filter.Q.value = 0.7;
      filter.connect(this.musicBus);

      const lfo = ctx.createOscillator();
      const lfoGain = ctx.createGain();
      lfo.frequency.value = 0.035;
      lfoGain.gain.value = 90;
      lfo.connect(lfoGain);
      lfoGain.connect(filter.frequency);
      lfo.start();

      const specs = [
        { f: 73.42, type: 'sine', gain: 0.19, detune: 0 },
        { f: 110.0, type: 'triangle', gain: 0.055, detune: 4 },
        { f: 146.83, type: 'sine', gain: 0.045, detune: -5 },
        { f: 220.0, type: 'sine', gain: 0.018, detune: 7 },
      ];
      for (const spec of specs) {
        const osc = ctx.createOscillator();
        const gain = ctx.createGain();
        osc.type = spec.type;
        osc.frequency.value = spec.f;
        osc.detune.value = spec.detune;
        gain.gain.value = 0;
        gain.gain.linearRampToValueAtTime(spec.gain, ctx.currentTime + 6);
        osc.connect(gain);
        gain.connect(filter);
        osc.start();
        this.droneNodes.push({ osc, gain });
      }

      // slow shimmer
      const shimmer = ctx.createOscillator();
      const shimmerGain = ctx.createGain();
      shimmer.type = 'sine';
      shimmer.frequency.value = 587.33;
      shimmerGain.gain.value = 0.008;
      const shimmerLfo = ctx.createOscillator();
      const shimmerLfoGain = ctx.createGain();
      shimmerLfo.frequency.value = 0.06;
      shimmerLfoGain.gain.value = 0.006;
      shimmerLfo.connect(shimmerLfoGain);
      shimmerLfoGain.connect(shimmerGain.gain);
      shimmer.connect(shimmerGain);
      shimmerGain.connect(this.delay);
      shimmer.start();
      shimmerLfo.start();
      this.shimmer = { shimmer, shimmerGain, shimmerLfo };

      const bell = () => {
        if (!this.ctx || this.muted) return;
        const notes = [SCALE[5], SCALE[6], SCALE[7], SCALE[8], SCALE[9], SCALE[4]];
        const f = notes[this.bellStep % notes.length] * (this.bellStep % 7 === 0 ? 0.5 : 1);
        this.bellStep++;
        this._bell(f, 0.05);
        if (Math.random() > 0.55) setTimeout(() => this._bell(f * 1.5, 0.025), 420);
      };
      this.bellTimer = setInterval(bell, 5400);
      setTimeout(bell, 2600);
    }

    _bell(freq, level = 0.04) {
      if (!this.ctx || this.muted) return;
      const ctx = this.ctx;
      const t = ctx.currentTime;
      const osc = ctx.createOscillator();
      const osc2 = ctx.createOscillator();
      const gain = ctx.createGain();
      osc.type = 'sine'; osc.frequency.value = freq;
      osc2.type = 'sine'; osc2.frequency.value = freq * 2.01;
      osc.connect(gain); osc2.connect(gain);
      gain.gain.setValueAtTime(0.0001, t);
      gain.gain.exponentialRampToValueAtTime(level, t + 0.02);
      gain.gain.exponentialRampToValueAtTime(0.0001, t + 4.6);
      gain.connect(this.delay);
      gain.connect(this.musicBus);
      osc.start(t); osc2.start(t);
      osc.stop(t + 4.8); osc2.stop(t + 4.8);
    }

    setMusic(value) {
      this.musicVolume = Math.max(0, Math.min(1, value / 100));
      if (this.musicBus && this.ctx) {
        this.musicBus.gain.cancelScheduledValues(this.ctx.currentTime);
        this.musicBus.gain.linearRampToValueAtTime(this.musicVolume * 0.3, this.ctx.currentTime + 0.3);
      }
    }

    setSfx(value) {
      this.sfxVolume = Math.max(0, Math.min(1, value / 100));
      if (this.sfxBus && this.ctx) {
        this.sfxBus.gain.cancelScheduledValues(this.ctx.currentTime);
        this.sfxBus.gain.linearRampToValueAtTime(this.sfxVolume * 0.55, this.ctx.currentTime + 0.2);
      }
    }

    setMuted(muted) {
      this.muted = muted;
      if (this.master && this.ctx) {
        this.master.gain.cancelScheduledValues(this.ctx.currentTime);
        this.master.gain.linearRampToValueAtTime(muted ? 0 : 0.85, this.ctx.currentTime + 0.25);
      }
    }

    _tone({ freq = 440, dur = 0.15, type = 'sine', level = 0.08, slide = 0, delay = 0 }) {
      if (!this.ctx || this.muted) return;
      const ctx = this.ctx;
      const t = ctx.currentTime + delay;
      const osc = ctx.createOscillator();
      const gain = ctx.createGain();
      osc.type = type;
      osc.frequency.setValueAtTime(freq, t);
      if (slide) osc.frequency.exponentialRampToValueAtTime(Math.max(30, freq + slide), t + dur);
      gain.gain.setValueAtTime(0.0001, t);
      gain.gain.exponentialRampToValueAtTime(level, t + 0.012);
      gain.gain.exponentialRampToValueAtTime(0.0001, t + dur);
      osc.connect(gain);
      gain.connect(this.sfxBus);
      osc.start(t);
      osc.stop(t + dur + 0.05);
    }

    _noise({ dur = 0.5, level = 0.12, cutoff = 900, delay = 0 }) {
      if (!this.ctx || this.muted) return;
      const ctx = this.ctx;
      const t = ctx.currentTime + delay;
      const buffer = ctx.createBuffer(1, ctx.sampleRate * dur, ctx.sampleRate);
      const data = buffer.getChannelData(0);
      for (let i = 0; i < data.length; i++) data[i] = (Math.random() * 2 - 1) * (1 - i / data.length);
      const src = ctx.createBufferSource();
      src.buffer = buffer;
      const filter = ctx.createBiquadFilter();
      filter.type = 'lowpass';
      filter.frequency.setValueAtTime(cutoff, t);
      filter.frequency.exponentialRampToValueAtTime(140, t + dur);
      const gain = ctx.createGain();
      gain.gain.setValueAtTime(level, t);
      gain.gain.exponentialRampToValueAtTime(0.0001, t + dur);
      src.connect(filter); filter.connect(gain); gain.connect(this.sfxBus);
      src.start(t);
    }

    click() { this._tone({ freq: 740, dur: 0.045, type: 'triangle', level: 0.035, slide: -180 }); }
    hover() { this._tone({ freq: 1180, dur: 0.025, type: 'sine', level: 0.012 }); }
    open() {
      this._tone({ freq: 392, dur: 0.35, type: 'sine', level: 0.05 });
      this._tone({ freq: 587.33, dur: 0.5, type: 'sine', level: 0.03, delay: 0.07 });
    }
    close() {
      this._tone({ freq: 392, dur: 0.28, type: 'sine', level: 0.035, slide: -60 });
    }
    select() {
      this._tone({ freq: 659.25, dur: 0.18, type: 'triangle', level: 0.045 });
      this._tone({ freq: 987.77, dur: 0.3, type: 'sine', level: 0.02, delay: 0.05 });
    }
    lock() {
      this._tone({ freq: 130, dur: 0.1, type: 'square', level: 0.03 });
      this._tone({ freq: 98, dur: 0.16, type: 'square', level: 0.025, delay: 0.09 });
    }
    power() {
      this._noise({ dur: 0.5, level: 0.05, cutoff: 2400 });
      this._tone({ freq: 180, dur: 0.5, type: 'sine', level: 0.06, slide: 540 });
      this._tone({ freq: 523.25, dur: 0.7, type: 'sine', level: 0.03, delay: 0.2 });
    }
    move() {
      this._noise({ dur: 0.35, level: 0.045, cutoff: 600 });
      this._tone({ freq: 220, dur: 0.2, type: 'sine', level: 0.03, slide: -40 });
    }
    battle() {
      this._noise({ dur: 0.8, level: 0.16, cutoff: 1500 });
      this._tone({ freq: 70, dur: 0.4, type: 'sine', level: 0.1, slide: -25 });
      this._tone({ freq: 160, dur: 0.18, type: 'square', level: 0.03, delay: 0.06 });
    }
    victory() {
      [523.25, 659.25, 783.99, 1046.5].forEach((f, i) => {
        this._tone({ freq: f, dur: 1.5, type: 'sine', level: 0.04, delay: i * 0.16 });
      });
      this._bell(523.25, 0.05);
      setTimeout(() => this._bell(783.99, 0.04), 700);
    }
    defeat() {
      [392, 311.13, 261.63, 196].forEach((f, i) => {
        this._tone({ freq: f, dur: 1.8, type: 'sine', level: 0.045, delay: i * 0.26 });
      });
      this._noise({ dur: 1.4, level: 0.05, cutoff: 300 });
    }
    save() {
      this._tone({ freq: 880, dur: 0.2, type: 'sine', level: 0.03 });
      this._tone({ freq: 1174.66, dur: 0.4, type: 'sine', level: 0.02, delay: 0.09 });
    }
    deny() {
      this._tone({ freq: 180, dur: 0.20, type: 'triangle', level: 0.035, slide: -40 });
    }
  }

  window.GATC_AUDIO = { SoundEngine };
})();

/* ═══════════════════════════════════════════════════════════
   Chronicle storage — options and save slots
   ═══════════════════════════════════════════════════════════ */
(function () {
  'use strict';

  const OPTIONS_KEY = 'gatc.options.v1';
  const SAVES_KEY = 'gatc.saves.v1';
  const SLOTS = ['auto', 'slot1', 'slot2', 'slot3'];
  const SLOT_LABEL = { auto: 'Autosave', slot1: 'Slot I', slot2: 'Slot II', slot3: 'Slot III' };

  const DEFAULT_OPTIONS = {
    music: 55,
    sfx: 70,
    reducedMotion: false,
    shake: true,
    muted: false,
  };

  function safeGet(key) {
    try { return window.localStorage.getItem(key); } catch { return null; }
  }
  function safeSet(key, value) {
    try { window.localStorage.setItem(key, value); return true; } catch { return false; }
  }

  function getOptions() {
    try {
      const parsed = JSON.parse(safeGet(OPTIONS_KEY) || '{}');
      return { ...DEFAULT_OPTIONS, ...parsed };
    } catch {
      return { ...DEFAULT_OPTIONS };
    }
  }
  function setOptions(options) {
    return safeSet(OPTIONS_KEY, JSON.stringify({ ...DEFAULT_OPTIONS, ...options }));
  }

  function getSaves() {
    try {
      const parsed = JSON.parse(safeGet(SAVES_KEY) || '{}');
      const result = {};
      for (const slot of SLOTS) {
        if (parsed[slot] && parsed[slot].state) result[slot] = parsed[slot];
      }
      return result;
    } catch {
      return {};
    }
  }
  function setSaves(saves) {
    return safeSet(SAVES_KEY, JSON.stringify(saves));
  }

  function metaFromState(state, outcome = state.outcome) {
    let provinces = 0;
    for (const owner of Object.values(state.owners || {})) if (owner === 'player') provinces++;
    return {
      turn: state.turns || 1,
      provinces,
      host: state.host || 0,
      faith: state.faith || 0,
      updatedAt: Date.now(),
      outcome: outcome || null,
    };
  }

  function save(slot, state, outcome = state.outcome) {
    if (!SLOTS.includes(slot)) return false;
    const saves = getSaves();
    saves[slot] = {
      state: JSON.parse(JSON.stringify(state)),
      meta: metaFromState(state, outcome),
    };
    return setSaves(saves);
  }

  function hasAnySave() {
    return Object.keys(getSaves()).length > 0;
  }

  function newestSave() {
    const saves = getSaves();
    let best = null;
    for (const [slot, entry] of Object.entries(saves)) {
      if (!best || (entry.meta.updatedAt || 0) > (best.meta.updatedAt || 0)) best = { slot, ...entry };
    }
    return best;
  }

  function remove(slot) {
    const saves = getSaves();
    if (!saves[slot]) return false;
    delete saves[slot];
    return setSaves(saves);
  }

  function formatDate(ts) {
    if (!ts) return '';
    try {
      return new Intl.DateTimeFormat('en', { month: 'short', day: 'numeric', hour: '2-digit', minute: '2-digit' }).format(new Date(ts));
    } catch {
      return '';
    }
  }

  window.GATC_SAVES = {
    SLOTS, SLOT_LABEL, DEFAULT_OPTIONS,
    getOptions, setOptions, getSaves, metaFromState, save, remove,
    hasAnySave, newestSave, formatDate,
  };
})();

/* ═══════════════════════════════════════════════════════════
   Conquest — game rules
   ═══════════════════════════════════════════════════════════ */
(function () {
  'use strict';
  const { PROVINCES, INITIAL, POWERS } = window.GATC_DATA;

  const rand = (min, max) => min + Math.random() * (max - min);
  const clamp = (v, min, max) => Math.max(min, Math.min(max, v));

  function defenseLabel(p) {
    if (p.capital === 'enemy') return 'Citadel';
    if (p.capital === 'player') return 'Sanctum';
    if (p.fort >= 1.25) return 'Walled';
    if (p.fort >= 1.15) return 'High';
    return 'Open';
  }

  class Conquest {
    constructor(state) {
      this.state = state ? Conquest.normalize(state) : Conquest.createState();
    }

    static createState() {
      return {
        version: 1,
        turns: 1,
        faith: 30,
        host: 8,
        enemyHost: 8,
        playerPos: 'sanctum',
        enemyPos: 'shadow',
        owners: { ...INITIAL.owners },
        garrisons: { ...INITIAL.garrisons },
        usedPowers: [],
        blessing: false,
        outcome: null,
        startedAt: Date.now(),
        log: [
          { turn: 1, type: 'system', text: 'The last Daughter of Dawn wakes beneath a dying sun.' },
          { turn: 1, type: 'system', text: 'Your host gathers at the Sanctum. The Shadow Citadel waits in the east.' },
          { turn: 1, text: 'Hold the Sanctum. Take the Citadel. Rekindle the dawn.' },
        ],
        stats: { battlesWon: 0, captured: 0, smites: 0, fallen: 0 },
      };
    }

    static normalize(state) {
      const base = Conquest.createState();
      const merged = {
        ...base,
        ...state,
        owners: { ...base.owners, ...(state.owners || {}) },
        garrisons: { ...base.garrisons, ...(state.garrisons || {}) },
        usedPowers: Array.isArray(state.usedPowers) ? state.usedPowers : [],
        stats: { ...base.stats, ...(state.stats || {}) },
        log: Array.isArray(state.log) ? state.log.slice(-60) : base.log,
      };
      if (!merged.playerPos) merged.playerPos = 'sanctum';
      if (!merged.enemyPos) merged.enemyPos = 'shadow';
      if (typeof merged.enemyHost !== 'number') merged.enemyHost = 8;
      if (typeof merged.host !== 'number') merged.host = 8;
      if (typeof merged.faith !== 'number') merged.faith = 30;
      merged.turns = Math.max(1, merged.turns || 1);
      return merged;
    }

    get s() { return this.state; }
    province(id) { return PROVINCES[id]; }
    owner(id) { return this.state.owners[id] || 'neutral'; }
    garrison(id) { return this.state.garrisons[id] || 0; }
    isAdjacent(id) {
      return Boolean(id && PROVINCES[this.state.playerPos]?.neighbors.includes(id));
    }
    isEnemyAdjacent(id) {
      return Boolean(id && PROVINCES[this.state.enemyPos]?.neighbors.includes(id));
    }
    isHostile(id) { return this.owner(id) !== 'player'; }
    playerProvinces() { return Object.keys(this.state.owners).filter(id => this.owner(id) === 'player'); }
    enemyProvinces() { return Object.keys(this.state.owners).filter(id => this.owner(id) === 'enemy'); }
    neutralProvinces() { return Object.keys(this.state.owners).filter(id => this.owner(id) === 'neutral'); }
    countProvinces(side) {
      return Object.values(this.state.owners).filter(o => o === side).length;
    }
    income(side = 'player') {
      return this.playerProvinces().reduce((sum, id) => sum + (PROVINCES[id].income || 0), 0) * (side === 'player' ? 1 : 0);
    }
    playerIncome() {
      return this.playerProvinces().reduce((sum, id) => sum + (PROVINCES[id].income || 0), 0);
    }
    defenseLabel(id) { return defenseLabel(PROVINCES[id]); }
    provincePower(id) {
      const p = PROVINCES[id];
      const garrison = this.garrison(id);
      let power = garrison * p.fort + 2;
      if (id === this.state.playerPos) power += this.state.host * 0.8;
      if (id === this.state.enemyPos) power += this.state.enemyHost * 0.8;
      if (p.capital === 'player') power += 2;
      return Math.round(power);
    }

    addLog(text, type = '', turn = this.state.turns) {
      this.state.log.push({ text, type, turn, id: Date.now() + Math.random() });
      if (this.state.log.length > 60) this.state.log = this.state.log.slice(-60);
    }

    // ── player actions ─────────────────────────────────────
    recruit() {
      if (this.state.outcome) return { ok: false, msg: 'The chronicle is closed.' };
      if (this.state.faith < 10) return { ok: false, msg: 'Not enough faith to muster.' };
      if (this.state.host >= 40) return { ok: false, msg: 'Your host cannot grow further.' };
      this.state.faith -= 10;
      this.state.host = Math.min(40, this.state.host + 2);
      this.addLog('Two more faithful take up arms. The host swells to ' + this.state.host + '.', 'good');
      return { ok: true, msg: '+2 warriors mustered', effect: 'recruit' };
    }

    fortify() {
      if (this.state.outcome) return { ok: false, msg: 'The chronicle is closed.' };
      if (this.state.faith < 8) return { ok: false, msg: 'Not enough faith to fortify.' };
      const id = this.state.playerPos;
      if (this.owner(id) !== 'player') return { ok: false, msg: 'Your host is not in a province you hold.' };
      const p = PROVINCES[id];
      const max = p.capital === 'player' ? 10 : (p.fort >= 1.2 ? 7 : 6);
      if (this.garrison(id) >= max) return { ok: false, msg: 'The garrison is already at full strength.' };
      this.state.faith -= 8;
      this.state.garrisons[id] = Math.min(max, this.garrison(id) + 2);
      this.addLog('Walls are manned at ' + p.name + '. Garrison ' + this.garrison(id) + '.', 'good');
      return { ok: true, msg: '+2 garrison at ' + p.name, effect: 'fortify', province: id };
    }

    usePower(powerId, targetId) {
      const power = POWERS[powerId];
      if (!power) return { ok: false, msg: 'Unknown power.' };
      if (this.state.outcome) return { ok: false, msg: 'The chronicle is closed.' };
      if (this.state.usedPowers.includes(powerId)) return { ok: false, msg: power.name + ' has already answered today.' };
      if (this.state.faith < power.cost) return { ok: false, msg: 'Not enough faith for ' + power.name + '.' };

      if (powerId === 'smite') {
        if (!targetId || this.owner(targetId) === 'player') return { ok: false, msg: 'Smite must fall upon a hostile province.' };
        if (this.garrison(targetId) <= 0) return { ok: false, msg: 'There is nothing left to smite there.' };
        this.state.faith -= power.cost;
        this.state.usedPowers.push(powerId);
        const before = this.garrison(targetId);
        this.state.garrisons[targetId] = Math.max(0, before - 3);
        this.state.stats.smites++;
        const p = PROVINCES[targetId];
        this.addLog('Dawnfire falls on ' + p.name + '. Its garrison falls from ' + before + ' to ' + this.garrison(targetId) + '.', 'good');
        return { ok: true, msg: 'Smite strikes ' + p.name, effect: 'smite', province: targetId, damage: before - this.garrison(targetId) };
      }

      if (powerId === 'bless') {
        if (this.state.blessing) return { ok: false, msg: 'Your host already carries the blessing.' };
        this.state.faith -= power.cost;
        this.state.usedPowers.push(powerId);
        this.state.blessing = true;
        this.addLog('The host is anointed. Your next battle burns 35% brighter.', 'good');
        return { ok: true, msg: 'Blessing granted', effect: 'bless' };
      }

      if (powerId === 'mend') {
        if (this.state.host >= 40) return { ok: false, msg: 'Your host is already whole.' };
        this.state.faith -= power.cost;
        this.state.usedPowers.push(powerId);
        this.state.host = Math.min(40, this.state.host + 4);
        this.addLog('Light closes the wounds of your faithful. Host restored to ' + this.state.host + '.', 'good');
        return { ok: true, msg: '+4 warriors restored', effect: 'mend' };
      }

      if (powerId === 'convert') {
        if (!targetId || this.owner(targetId) !== 'neutral') return { ok: false, msg: 'Only a free province can be converted.' };
        const p = PROVINCES[targetId];
        const besideRealm = p.neighbors.some(n => this.owner(n) === 'player');
        if (!besideRealm) return { ok: false, msg: 'The province must border your realm.' };
        this.state.faith -= power.cost;
        this.state.usedPowers.push(powerId);
        this.state.owners[targetId] = 'player';
        this.state.garrisons[targetId] = Math.max(2, this.garrison(targetId));
        this.addLog(p.name + ' hears the old oath and joins the Dawn without a blade drawn.', 'good');
        return { ok: true, msg: p.name + ' joins the Dawn', effect: 'convert', province: targetId };
      }

      return { ok: false, msg: 'The power does not answer.' };
    }

    move(targetId) {
      if (this.state.outcome) return { ok: false, kind: 'none' };
      if (!PROVINCES[targetId]) return { ok: false, kind: 'none', msg: 'Unknown province.' };
      if (targetId === this.state.playerPos) return { ok: false, kind: 'none', msg: 'Your host is already here.' };
      if (!this.isAdjacent(targetId)) return { ok: false, kind: 'none', msg: 'That province is beyond your march.' };

      const p = PROVINCES[targetId];
      if (this.owner(targetId) === 'player') {
        this.state.playerPos = targetId;
        this.addLog('The host marches to ' + p.name + '.', '');
        return { ok: true, kind: 'move', target: targetId };
      }
      return this.playerBattle(targetId);
    }

    playerBattle(targetId) {
      const id = this.state.playerPos;
      const from = PROVINCES[id];
      const target = PROVINCES[targetId];
      const garrison = this.garrison(targetId);
      const bless = this.state.blessing;

      const atk = Math.round(this.state.host * (bless ? 1.35 : 1) * rand(0.9, 1.1) + 3);
      let def = Math.round(garrison * target.fort * rand(0.9, 1.1) + 2);
      const enemySupport = this.state.enemyPos === targetId ? Math.round(this.state.enemyHost * 0.8) : 0;
      def += enemySupport;
      if (target.capital === 'player') def += 2;

      const win = atk > def;
      let losses = 0;
      let defenderLosses = 0;

      if (win) {
        losses = clamp(Math.round(garrison * rand(0.32, 0.55)) + 1, 1, Math.max(1, this.state.host - 1));
        this.state.host = Math.max(1, this.state.host - losses);
        defenderLosses = garrison;
        this.state.owners[targetId] = 'player';
        this.state.garrisons[targetId] = 1;
        this.state.playerPos = targetId;
        this.state.stats.battlesWon++;
        this.state.stats.captured++;
        this.state.faith += 4;
        this.addLog(target.name + ' falls to the Dawn. ' + losses + ' warriors lost, 4 faith gathered.', 'good');
        if (targetId === 'shadow') this.finish('victory');
      } else {
        losses = clamp(Math.round(this.state.host * rand(0.18, 0.32)), 1, Math.max(1, this.state.host - 1));
        this.state.host = Math.max(1, this.state.host - losses);
        defenderLosses = 1;
        this.state.garrisons[targetId] = Math.max(1, garrison - 1);
        this.addLog('The assault on ' + target.name + ' is thrown back. ' + losses + ' warriors lost.', 'bad');
      }

      if (bless) {
        this.state.blessing = false;
        this.addLog('The blessing spends itself in the fire of battle.', 'system');
      }

      return {
        ok: true, kind: 'battle',
        target: targetId,
        from: id,
        defender: this.owner(targetId) === 'player' ? (targetId === 'shadow' ? 'enemy' : 'neutral') : (targetId === 'shadow' || this.state.owners[targetId] === 'enemy' ? 'enemy' : 'neutral'),
        defenderName: target.name,
        atk, def, win, losses, defenderLosses,
        garrisonBefore: garrison,
        blessed: bless,
        capital: target.capital || null,
        enemySupport,
        outcome: this.state.outcome,
      };
    }

    finish(outcome) {
      this.state.outcome = outcome;
      if (outcome === 'victory') {
        this.addLog('The Shadow Citadel is taken. Dawn pours through the broken seal.', 'good');
      } else {
        this.addLog('The Sanctum of Dawn has fallen. The last light goes out.', 'bad');
      }
    }

    // ── enemy turn ────────────────────────────────────────
    beginEnemyTurn() {
      if (this.state.outcome) return { growth: 0 };
      const provinces = this.enemyProvinces();
      const growth = 1 + Math.floor(provinces.length / 3);
      this.state.enemyHost = Math.min(40, this.state.enemyHost + growth);
      for (const id of provinces) {
        const p = PROVINCES[id];
        const max = p.capital === 'enemy' ? 12 : (p.fort >= 1.2 ? 6 : 4);
        if (this.garrison(id) < max) this.state.garrisons[id] = Math.min(max, this.garrison(id) + 1);
      }
      return { growth, enemyHost: this.state.enemyHost };
    }

    _bfsPath(from, goalTest) {
      const queue = [[from]];
      const seen = new Set([from]);
      while (queue.length) {
        const path = queue.shift();
        const last = path[path.length - 1];
        if (goalTest(last)) return path;
        for (const n of PROVINCES[last].neighbors) {
          if (seen.has(n)) continue;
          seen.add(n);
          queue.push([...path, n]);
        }
      }
      return null;
    }

    _defenseAt(id) {
      const p = PROVINCES[id];
      let def = this.garrison(id) * p.fort + 2;
      if (id === this.state.playerPos) def += this.state.host * 0.8;
      if (p.capital === 'player') def += 2;
      return def;
    }

    enemyAct() {
      const s = this.state;
      if (s.outcome) return { kind: 'none' };
      const pos = s.enemyPos;
      const adjacent = PROVINCES[pos].neighbors.slice();
      const playerTargets = adjacent.filter(id => this.owner(id) === 'player');
      const neutralTargets = adjacent.filter(id => this.owner(id) === 'neutral');
      const aggression = s.turns >= 4 || this.enemyProvinces().length >= 6 || s.enemyHost >= 15;

      // 1 · strike a player province when it looks breakable
      playerTargets.sort((a, b) => this._defenseAt(a) - this._defenseAt(b));
      for (const target of playerTargets) {
        const def = this._defenseAt(target);
        const mustStopDawn = target === 'sanctum';
        if (aggression || s.enemyHost >= def * 1.18 || mustStopDawn) {
          return this.enemyBattle(target);
        }
      }

      // 2 · expand into a free province
      if (neutralTargets.length) {
        neutralTargets.sort((a, b) => this._defenseAt(a) - this._defenseAt(b));
        const target = neutralTargets[0];
        const def = this._defenseAt(target);
        if (s.enemyHost >= def * 1.08) return this.enemyBattle(target);
      }

      // 3 · march toward the nearest province still held by the Dawn
      const playerIds = this.playerProvinces();
      let goal = 'sanctum';
      if (playerIds.length) {
        let best = Infinity;
        for (const id of playerIds) {
          const path = this._bfsPath(pos, cur => cur === id);
          if (path && path.length < best) { best = path.length; goal = id; }
        }
      }
      const path = this._bfsPath(pos, cur => cur === goal);
      if (path && path.length > 1) {
        const next = path[1];
        if (this.owner(next) === 'player') return this.enemyBattle(next);
        if (this.owner(next) === 'neutral') {
          const def = this._defenseAt(next);
          if (s.enemyHost >= def * 1.05) return this.enemyBattle(next);
          s.enemyHost = Math.min(40, s.enemyHost + 1);
          this.addLog('The Hollow host gathers at ' + PROVINCES[pos].name + ', waiting for more dead.', 'bad');
          return { kind: 'hold', at: pos };
        }
        s.enemyPos = next;
        this.addLog('Hollow banners move through ' + PROVINCES[next].name + '.', 'bad');
        return { kind: 'move', target: next };
      }

      this.addLog('The Hollow host holds its ground at ' + PROVINCES[pos].name + '.', 'bad');
      return { kind: 'hold', at: pos };
    }

    enemyBattle(targetId) {
      const s = this.state;
      const target = PROVINCES[targetId];
      const garrison = this.garrison(targetId);
      const atk = Math.round(s.enemyHost * rand(0.9, 1.1) + 3);
      let def = Math.round(garrison * target.fort * rand(0.9, 1.1) + 2);
      const playerSupport = s.playerPos === targetId ? Math.round(s.host * 0.8) : 0;
      def += playerSupport;
      if (target.capital === 'player') def += 2;

      const win = atk > def;
      let losses = 0;
      let defenderLosses = 0;

      if (win) {
        losses = clamp(Math.round(garrison * rand(0.3, 0.52)) + 1, 1, Math.max(1, s.enemyHost - 1));
        s.enemyHost = Math.max(1, s.enemyHost - losses);
        defenderLosses = garrison;
        s.owners[targetId] = 'enemy';
        s.garrisons[targetId] = 1;
        s.enemyPos = targetId;
        if (target.capital === 'player') {
          s.stats.fallen++;
          this.addLog(target.name + ' is overrun. The altar fire dies.', 'bad');
          this.finish('defeat');
        } else {
          this.addLog('The Hollow host takes ' + target.name + '. ' + losses + ' of its soldiers fall.', 'bad');
        }
      } else {
        losses = clamp(Math.round(s.enemyHost * rand(0.2, 0.34)), 1, Math.max(1, s.enemyHost - 1));
        s.enemyHost = Math.max(1, s.enemyHost - losses);
        defenderLosses = 1;
        s.garrisons[targetId] = Math.max(1, garrison - 1);
        this.addLog('The Dawn holds ' + target.name + '. The Hollow host loses ' + losses + '.', 'good');
      }

      return {
        kind: 'battle',
        target: targetId,
        defender: 'player',
        defenderName: target.name,
        atk, def, win, losses, defenderLosses,
        garrisonBefore: garrison,
        support: playerSupport,
        capital: target.capital || null,
        outcome: s.outcome,
      };
    }

    startPlayerTurn() {
      if (this.state.outcome) return { income: 0, garrisonGrowth: 0 };
      this.state.turns++;
      this.state.usedPowers = [];
      const income = this.playerIncome();
      this.state.faith += income;
      let grown = 0;
      for (const id of this.playerProvinces()) {
        const p = PROVINCES[id];
        const max = p.capital === 'player' ? 10 : (p.fort >= 1.2 ? 7 : 6);
        if (this.garrison(id) < max) {
          this.state.garrisons[id] = Math.min(max, this.garrison(id) + 1);
          grown++;
        }
      }
      this.addLog('Turn ' + this.state.turns + ' — the Dawn gathers ' + income + ' faith.', 'system');
      return { income, garrisonGrowth: grown, turn: this.state.turns };
    }

    // ── helpers for UI ────────────────────────────────────
    actionFor(id) {
      if (this.state.outcome) return { type: 'none', label: 'The chronicle is closed', disabled: true };
      if (!this.isAdjacent(id)) return { type: 'none', label: 'Beyond your march', disabled: true };
      if (this.owner(id) === 'player') {
        return { type: 'move', label: 'March to ' + PROVINCES[id].short, disabled: false };
      }
      const power = this.provincePower(id);
      const blessed = this.state.blessing ? Math.round(this.state.host * 1.35 + 3) : this.state.host + 3;
      return {
        type: 'attack',
        label: 'Attack ' + PROVINCES[id].short,
        disabled: false,
        risky: blessed < power,
        power,
      };
    }

    remainingPowers() {
      return Object.keys(POWERS).filter(id => !this.state.usedPowers.includes(id));
    }
  }

  window.GATC_GAME = { Conquest };
})();

