Now write main.js. It's large (~700-900 lines). I'll split into two writes? Write tool replaces whole file. Could write part 1 then append via edit? Simpler: one write, keep within token limits. Let's construct carefully.

Main structure:

(function(){
'use strict';
const {PROVINCES, POWERS, GLYPHS} = window.GATC_DATA;
const S = window.GATC_SAVES;
const $ = id => document.getElementById(id);
const qs = sel => document.querySelector(sel);

refs = {...}
options = S.getOptions();
audio = new GATC_AUDIO.SoundEngine(options);
let game=null, selected='sanctum', targeting=null, busy=false, flow=0, battleResolve=null, loadContext='menu', optionsReturn=null, toastTimer=null, bannerTimer=null, lastFocus=null;
const NON_DISMISSIBLE = new Set(['modal-battle','modal-result']);

init functions.

Apply options:
function applyOptions(){
 audio.setMusic(options.music); audio.setSfx(options.sfx); audio.setMuted(options.muted);
 body.classList.toggle('reduced-motion', options.reducedMotion);
 body.classList.toggle('no-shake', !options.shake) — no CSS needed; check in shake call.
 update sliders and toggles.
 updateSoundButton.
}
Note audio.setMusic before ctx exists just stores; constructor values already. Fine.

Sound button aria: muted → pressed true; icon use href. `btnSound.querySelector('use').setAttribute('href', ...)`. sprites symbols `#i-muted`, `#i-sound`.

Menu setup:
document.querySelectorAll('[data-menu]').forEach(btn => click => handleMenu(action)).
handleMenu:
 new: startIntro()
