 busy=true; targeting=null; const run=++flow; render();
 btnEndTurn label busy via render; showBanner('The Hollow stirs','The shadow answers your move');
 audio.click();
 await wait(500); if run!==flow return;
 const growth = game.beginEnemyTurn();
 if (growth.growth) game.addLog(`The Hollow host swells by ${growth.growth} at the Shadow Citadel.`, 'bad');
 renderHUD(); renderLog(); // state changed
 await wait(700); if run!==flow return;
 const ev = game.enemyAct();
 renderAllExcept? renderHUD, log, map (token movement), province.
 updateAll();
 await wait(ev.kind==='battle'?700:500); if run!==flow return;
 if (ev.kind==='battle') {
   audio.battle();
   map.flashProvince(ev.target, ev.win ? 'capture' : 'smite')? For enemy attack, use shake and flash target.
   if (options.shake) map.shake();
   await showBattle(ev, false);
   if (run!==flow) return;
   map.flashProvince(ev.target, ev.win ? 'smite' : 'capture'); // flash after
   updateAll();
   if (ev.outcome==='defeat') { finishResult('defeat'); return; }
   await wait(600); if run!==flow return;
 }
 if (game.state.outcome==='defeat') { finishResult('defeat'); return; }
 const start = game.startPlayerTurn();
 GATC_SAVES.save('auto', game.state);
 busy=false;
 updateAll();
 showBanner(`Turn ${start.turn}`, `The Dawn gathers ${start.income} faith`);
 showToast(`+${start.income} faith · ${start.garrisonGrowth} garrison${...}`, 'is-good');
 bumpStat('stat-faith'); bumpStat('stat-turn');
 audio.select();
 updateMenuSaveCount();
}
