Wait helper: const wait = ms => new Promise(r => setTimeout(r, options.reducedMotion? Math.min(ms,120):ms)); But if busy and user leaves, flow check.

Battle modal:
function showBattle(ev, playerAttacking) {
 return new Promise(resolve => {
  battleResolve = resolve;
  // Fill
  const modal = ...
  if playerAttacking:
    left name "Host of Dawn"; left troops = game.state.host + ev.losses (pre-loss); left crest player
    right name ev.defenderName; right troops ev.garrisonBefore; right crest class based on ev.defender (neutral?) keep enemy styling for both.
    title = ev.win ? 'The line breaks' : 'The assault falters'
    atkPower = ev.atk; defPower = ev.def; bars: left atk, right def.
    outcome text...
  else:
    left = Dawn defender; troops = ev.garrisonBefore; right = Hollow host; troops = state.enemyHost + ev.losses
    Dawn power = ev.def; Hollow power = ev.atk.
    Bar left def, right atk.
    title = ev.win ? 'The Hollow breaks through' : 'The Dawn holds'
  // set bar labels? The labels are static "Dawn"/"Hollow" in HTML. Values set. Good.
  // Bar max = max(atk,def)*1.15; widths after delay.
  battleLosses innerHTML:
   if playerAttacking: `Dawn <b class=loss>−${ev.losses}</b> · ${defenderName} <b class=loss>−${ev.defenderLosses}</b>${ev.win?' <span class=...>Province taken</span>':''}`
   else: `Hollow <b class=loss>−${ev.losses}</b> · Dawn <b class=loss>−${(ev.defenderLosses+ev.playerLosses)}</b>${ev.win?' <span>Province lost</span>':''}`
  openModal('modal-battle', {focusContinue:true}) but don't play open sound.
  requestAnimationFrame + timeout to set widths 50ms.
  audio.battle();
 });
}
