 setTimeout(()=>focusEl?.focus({preventScroll:true}),50);
}
function closeModal(id, opts={}) {
 const el=$(id); if(!el || el.hidden) return;
 el.hidden=true;
 const i=modalStack.lastIndexOf(id); if(i>=0) modalStack.splice(i,1);
 if (!opts.silent) audio.close();
 if (optionsReturn && id==='modal-options') { const ret=optionsReturn; optionsReturn=null; openModal(ret, {silent:true}); }
 restore focus lastFocus if visible.
}
