.preset-card__stats b { font-family: var(--serif); font-size: 12px; font-weight: 500; color: #d8cdb4; }
.preset-note {
  flex: none;
  margin: 0;
  padding: 0 clamp(20px, 2.8vw, 34px) 20px;
  font-size: 12px;
  font-style: italic;
  line-height: 1.5;
  color: #6d7182;
}

.scenario-bottom {
  flex: none;
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 18px;
  padding-top: 10px;
  border-top: 1px solid rgba(232, 199, 122, 0.14);
}
.scenario-hint {
  display: flex;
  align-items: center;
  gap: 8px;
  font-family: var(--body);
  font-style: italic;
  font-size: 14px;
  color: #8e92a2;
}
.scenario-hint__mark { color: var(--gold); font-size: 8px; animation: twinkle 3s ease-in-out infinite alternate; }
.scenario-actions { display: flex; align-items: center; gap: 20px; }
.scenario-prologue { white-space: nowrap; }
.scenario-actions .btn { padding: 12px 26px; }

/* app toast */
.app-toast {
  position: fixed;
  left: 50%;
  bottom: 6vh;
  z-index: 280;
  transform: translate(-50%, 10px);
  max-width: min(90vw, 440px);
  padding: 10px 20px;
  border: 1px solid rgba(232, 199, 122, 0.3);
  border-radius: 2px;
  background: rgba(8, 11, 20, 0.96);
  box-shadow: 0 14px 44px rgba(0, 0, 0, 0.55);
  font-family: var(--body);
  font-size: 14px;
  font-style: italic;
  text-align: center;
  color: #ded5c2;
  opacity: 0;
  pointer-events: none;
  transition: opacity 0.3s, transform 0.3s;
}
.app-toast.is-visible { opacity: 1; transform: translate(-50%, 0); }
.app-toast.is-bad { border-color: rgba(226, 119, 124, 0.4); color: #ecc0c3; }
.app-toast.is-good { border-color: rgba(232, 199, 122, 0.5); color: var(--gold-bright); }

/* option sections + difficulty */
.option-section {
  display: flex;
  align-items: center;
  gap: 10px;
  margin: 18px 0 0;
  padding-top: 14px;
  border-top: 1px solid rgba(232, 199, 122, 0.13);
  font-family: var(--serif);
  font-size: 8px;
  letter-spacing: 0.26em;
  text-transform: uppercase;
  color: var(--gold-dim);
