.option-section::after { content: ''; flex: 1; height: 1px; background: linear-gradient(90deg, rgba(232, 199, 122, 0.25), transparent); }
.option-section + .option-row { padding-top: 9px; }
.option-row--difficulty { align-items: center; }
.segmented {
  flex: none;
  display: flex;
  border: 1px solid rgba(232, 199, 122, 0.24);
  border-radius: 2px;
  overflow: hidden;
  background: rgba(0, 0, 0, 0.18);
}
.seg {
  border: 0;
  border-left: 1px solid rgba(232, 199, 122, 0.12);
  background: transparent;
  padding: 7px 12px;
  font-family: var(--serif);
  font-size: 7.5px;
  letter-spacing: 0.14em;
  text-transform: uppercase;
  color: #7c8091;
  transition: background 0.25s, color 0.25s;
}
.seg:first-child { border-left: 0; }
.seg:hover { color: var(--gold-bright); background: rgba(232, 199, 122, 0.07); }
.seg[aria-checked='true'] {
  color: var(--gold-bright);
  background: linear-gradient(180deg, rgba(232, 199, 122, 0.2), rgba(232, 199, 122, 0.08));
  box-shadow: inset 0 -2px 0 rgba(232, 199, 122, 0.65);
}
.option-note {
  margin: 3px 0 0;
  text-align: right;
  font-size: 11.5px;
  font-style: italic;
  line-height: 1.45;
  color: #686c7d;
}

