450:     if (game.state.usedPowers.includes(id)) {
451:       audio.deny();
452:       showToast(power.name + ' has already answered today.', 'is-bad');
453:       return;
454:     }
455:     if (game.state.faith < power.cost) {
456:       audio.deny();
457:       showToast('Not enough faith for ' + power.name + '.', 'is-bad');
458:       return;
459:     }
