478:     const targets = targetSetFor(id);
479:     if (!targets.size) {
480:       audio.deny();
481:       showToast(id === 'convert' ? 'No free province borders your realm.' : 'No valid target for ' + power.name + '.', 'is-bad');
482:       return;
