491:   function targetSetFor(id) {
492:     if (id === 'smite') {
493:       return new Set(Object.keys(PROVINCES).filter(pid => game.owner(pid) !== 'player' && game.garrison(pid) > 0));
494:     }
495:     if (id === 'convert') {
496:       return new Set(Object.keys(PROVINCES).filter(pid =>
497:         game.owner(pid) === 'neutral' && PROVINCES[pid].neighbors.some(n => game.owner(n) === 'player')
498:       ));
499:     }
500:     return new Set();
501:   }
