508:       return;
509:     }
510:     const powerId = targeting;
511:     const result = game.usePower(powerId, id);
512:     if (!result.ok) {
513:       audio.deny();
514:       showToast(result.msg, 'is-bad');
515:       return;
516:     }
517:     audio.power();
518:     if (powerId === 'smite') map.flashProvince(id, 'smite');
519:     targeting = null;
520:     if (result.effect === 'convert') selected = id;
521:     updateAll();
522:     bump('stat-faith');
523:     if (result.effect === 'convert') bump('stat-provinces');
524:     showToast(result.msg, 'is-good');
525:     autoSave();
