683:   function showBattle(event, playerAttacking) {
684:     return new Promise(resolve => {
685:       battleResolve = resolve;
686: 
687:       const dawnPower = playerAttacking ? event.atk : event.def;
688:       const hollowPower = playerAttacking ? event.def : event.atk;
689:       const dawnTroops = playerAttacking ? game.state.host + event.losses : event.garrisonBefore;
690:       const hollowTroops = playerAttacking ? event.garrisonBefore : game.state.enemyHost + event.losses;
691:       const maxPower = Math.max(1, dawnPower, hollowPower) * 1.12;
692: 
693:       battleAtkTroops.textContent = dawnTroops;
694:       battleDefTroops.textContent = hollowTroops;
695:       battleAtkPower.textContent = dawnPower;
696:       battleDefPower.textContent = hollowPower;
697:       battleDefName.textContent = playerAttacking ? event.defenderName : 'Hollow Legion';
698:       battleAtkFill.style.width = '0%';
699:       battleDefFill.style.width = '0%';
700: 
701:       const playerWon = playerAttacking ? event.win : !event.win;
702:       if (playerAttacking) {
703:         battleTitle.textContent = event.win ? 'The line breaks' : 'The assault falters';
704:       } else {
705:         battleTitle.textContent = event.win ? 'The Hollow breaks through' : 'The Dawn holds';
706:       }
707: 
708:       const outcomeText = playerAttacking
709:         ? (event.win ? 'Your host carves through the defenders of ' + event.defenderName + '.' : 'Steel rings, but the defenders of ' + event.defenderName + ' do not yield.')
710:         : (event.win ? 'The dark tide rolls over ' + event.defenderName + '.' : 'The faithful of ' + event.defenderName + ' throw back the dark.');
711:       battleOutcome.textContent = outcomeText;
712:       battleOutcome.classList.toggle('is-win', playerWon);
713:       battleOutcome.classList.toggle('is-loss', !playerWon);
714: 
715:       if (playerAttacking) {
716:         battleLosses.innerHTML =
717:           '<span>Dawn <b class="loss">−' + event.losses + '</b></span>' +
718:           '<span>' + event.defenderName + ' <b class="loss">−' + event.defenderLosses + '</b></span>' +
719:           (event.win ? '<span class="gain">Province taken</span>' : '');
720:       } else {
721:         const dawnLosses = (event.defenderLosses || 0) + (event.playerLosses || 0);
722:         battleLosses.innerHTML =
723:           '<span>Hollow <b class="loss">−' + event.losses + '</b></span>' +
724:           '<span>Dawn <b class="loss">−' + dawnLosses + '</b></span>' +
725:           (event.win ? '<span class="loss">Province lost</span>' : '<span class="gain">Dawn holds</span>');
726:       }
727:       battleLosses.hidden = false;
728: 
729:       openModal('modal-battle', { silent: true });
730:       requestAnimationFrame(() => {
731:         setTimeout(() => {
732:           battleAtkFill.style.width = Math.min(100, (dawnPower / maxPower) * 100) + '%';
733:           battleDefFill.style.width = Math.min(100, (hollowPower / maxPower) * 100) + '%';
734:         }, options.reducedMotion ? 10 : 120);
735:       });
736:     });
737:   }
