901:       const slotLabel = slot === 'auto' ? 'AUTO' : SAVES.SLOT_LABEL[slot].replace('Slot ', '');
902:       const title = document.createElement('span');
903:       title.className = 'save-row__title';
904:       title.textContent = 'Turn ' + (meta.turn || 1) + ' · ' + (meta.provinces || 0) + ' provinces';
