274:     beginEnemyTurn() {
275:       if (this.state.outcome) return { growth: 0 };
276:       const provinces = this.enemyProvinces();
277:       const growth = Math.max(1, this.fate.growthBase + Math.floor(provinces.length / 3));
278:       this.state.enemyHost = Math.min(40, this.state.enemyHost + growth);
279:       for (const id of provinces) {
280:         const p = PROVINCES[id];
281:         const max = p.capital === 'enemy' ? 12 : (p.fort >= 1.2 ? 6 : 4);
282:         if (this.garrison(id) < max) this.state.garrisons[id] = Math.min(max, this.garrison(id) + 1);
283:       }
284:       return { growth, enemyHost: this.state.enemyHost };
285:     }
286: 
287:     _bfsPath(from, goalTest) {
288:       const queue = [[from]];
289:       const seen = new Set([from]);
290:       while (queue.length) {
291:         const path = queue.shift();
292:         const last = path[path.length - 1];
293:         if (goalTest(last)) return path;
294:         for (const n of PROVINCES[last].neighbors) {
295:           if (seen.has(n)) continue;
296:           seen.add(n);
297:           queue.push([...path, n]);
298:         }
299:       }
300:       return null;
301:     }
302: 
303:     _defenseAt(id) {
304:       const p = PROVINCES[id];
305:       let def = this.garrison(id) * p.fort + 2;
306:       if (id === this.state.playerPos) def += this.state.host * 0.8;
307:       if (p.capital === 'player') def += 2;
308:       return def;
309:     }
310: 
311:     enemyAct() {
312:       const s = this.state;
313:       if (s.outcome) return { kind: 'none' };
314:       const pos = s.enemyPos;
315:       const adjacent = PROVINCES[pos].neighbors.slice();
316:       const playerTargets = adjacent.filter(id => this.owner(id) === 'player');
317:       const neutralTargets = adjacent.filter(id => this.owner(id) === 'neutral');
318:       const aggression = s.turns >= this.fate.aggressionTurn || this.enemyProvinces().length >= 6 || s.enemyHost >= 15;
319: 
320:       // 1 · strike a player province when it looks breakable
321:       playerTargets.sort((a, b) => this._defenseAt(a) - this._defenseAt(b));
322:       for (const target of playerTargets) {
323:         const def = this._defenseAt(target);
324:         const mustStopDawn = target === 'sanctum';
325:         if (aggression || s.enemyHost >= def * 1.18 || mustStopDawn) {
326:           return this.enemyBattle(target);
327:         }
328:       }
329: 
330:       // 2 · expand into a free province
331:       if (neutralTargets.length) {
332:         neutralTargets.sort((a, b) => this._defenseAt(a) - this._defenseAt(b));
333:         const target = neutralTargets[0];
334:         const def = this._defenseAt(target);
335:         if (s.enemyHost >= def * 1.08) return this.enemyBattle(target);
336:       }
337: 
338:       // 3 · march toward the nearest province still held by the Dawn
339:       const playerIds = this.playerProvinces();
340:       let goal = 'sanctum';
341:       if (playerIds.length) {
342:         let best = Infinity;
343:         for (const id of playerIds) {
344:           const path = this._bfsPath(pos, cur => cur === id);
345:           if (path && path.length < best) { best = path.length; goal = id; }
346:         }
347:       }
348:       const path = this._bfsPath(pos, cur => cur === goal);
349:       if (path && path.length > 1) {
350:         const next = path[1];
351:         if (this.owner(next) === 'player') return this.enemyBattle(next);
352:         if (this.owner(next) === 'neutral') {
353:           const def = this._defenseAt(next);
354:           if (s.enemyHost >= def * 1.05) return this.enemyBattle(next);
355:           s.enemyHost = Math.min(40, s.enemyHost + 1);
356:           this.addLog('The Hollow host gathers at ' + PROVINCES[pos].name + ', waiting for more dead.', 'bad');
357:           return { kind: 'hold', at: pos };
358:         }
359:         s.enemyPos = next;
360:         this.addLog('Hollow banners move through ' + PROVINCES[next].name + '.', 'bad');
361:         return { kind: 'move', target: next };
362:       }
363: 
364:       this.addLog('The Hollow host holds its ground at ' + PROVINCES[pos].name + '.', 'bad');
365:       return { kind: 'hold', at: pos };
366:     }
367: 
368:     enemyBattle(targetId) {
369:       const s = this.state;
370:       const target = PROVINCES[targetId];
371:       const garrison = this.garrison(targetId);
372:       const atk = Math.round(s.enemyHost * rand(0.9, 1.1) + 3 + this.fate.enemyBonus);
373:       let def = Math.round(garrison * target.fort * rand(0.9, 1.1) + 2);
374:       const playerSupport = s.playerPos === targetId ? Math.round(s.host * 0.8) : 0;
375:       def += playerSupport;
376:       if (target.capital === 'player') def += 2;
377: 
378:       const win = atk > def;
379:       let losses = 0;
380:       let defenderLosses = 0;
381:       let playerLosses = 0;
382: 
383:       if (win) {
384:         losses = clamp(Math.round(garrison * rand(0.3, 0.52)) + 1, 1, Math.max(1, s.enemyHost - 1));
385:         s.enemyHost = Math.max(1, s.enemyHost - losses);
386:         defenderLosses = garrison;
387:         s.owners[targetId] = 'enemy';
388:         s.garrisons[targetId] = 1;
389:         s.enemyPos = targetId;
390:         if (s.playerPos === targetId) {
391:           playerLosses = clamp(Math.round(garrison * 0.4), 1, Math.max(1, s.host - 1));
392:           s.host = Math.max(1, s.host - playerLosses);
393:           // the Dawn's field host withdraws to the nearest friendly province
394:           const refuge = PROVINCES[targetId].neighbors.find(n => s.owners[n] === 'player');
395:           if (refuge) {
396:             s.playerPos = refuge;
397:             this.addLog('Your host falls back to ' + PROVINCES[refuge].name + ' with ' + s.host + ' warriors.', 'bad');
398:           }
399:         }
400:         if (target.capital === 'player') {
401:           s.stats.fallen++;
402:           this.addLog(target.name + ' is overrun. The altar fire dies.', 'bad');
403:           this.finish('defeat');
404:         } else {
405:           this.addLog('The Hollow host takes ' + target.name + '. ' + losses + ' of its soldiers fall.', 'bad');
406:         }
407:       } else {
408:         losses = clamp(Math.round(s.enemyHost * rand(0.2, 0.34)), 1, Math.max(1, s.enemyHost - 1));
409:         s.enemyHost = Math.max(1, s.enemyHost - losses);
410:         defenderLosses = 1;
411:         s.garrisons[targetId] = Math.max(1, garrison - 1);
412:         if (s.playerPos === targetId) {
413:           playerLosses = clamp(Math.round(garrison * rand(0.15, 0.3)), 1, Math.max(1, s.host - 1));
414:           s.host = Math.max(1, s.host - playerLosses);
415:         }
416:         this.addLog('The Dawn holds ' + target.name + '. The Hollow host loses ' + losses + '.', 'good');
417:       }
418: 
419:       return {
420:         kind: 'battle',
421:         target: targetId,
422:         defender: 'player',
423:         defenderName: target.name,
424:         atk, def, win, losses, defenderLosses,
425:         playerLosses,
426:         garrisonBefore: garrison,
427:         support: playerSupport,
428:         capital: target.capital || null,
429:         outcome: s.outcome,
430:       };
431:     }
432: 
433:     startPlayerTurn() {
434:       if (this.state.outcome) return { income: 0, garrisonGrowth: 0 };
435:       this.state.turns++;
436:       this.state.usedPowers = [];
437:       const income = this.playerIncome();
438:       this.state.faith += income;
439:       let grown = 0;
440:       for (const id of this.playerProvinces()) {
441:         const p = PROVINCES[id];
442:         const max = p.capital === 'player' ? 10 : (p.fort >= 1.2 ? 7 : 6);
443:         if (this.garrison(id) < max) {
444:           this.state.garrisons[id] = Math.min(max, this.garrison(id) + 1);
445:           grown++;
446:         }
447:       }
448:       this.addLog('Turn ' + this.state.turns + ' — the Dawn gathers ' + income + ' faith.', 'system');
449:       return { income, garrisonGrowth: grown, turn: this.state.turns };
450:     }
