input.newString:
/* ═══════════════════════════════════════════════════════════
   CHARACTER SELECT
   ═══════════════════════════════════════════════════════════ */
.screen--character {
  position: fixed;
  inset: 0;
  z-index: 4;
  display: flex;
  overflow: hidden;
  background:
    radial-gradient(ellipse at 78% 16%, rgba(232, 199, 122, 0.08), transparent 54%),
    radial-gradient(ellipse at 20% 100%, rgba(80, 60, 30, 0.12), transparent 55%),
    linear-gradient(180deg, rgba(5, 7, 13, 0.35), rgba(5, 7, 13, 0.82));
  animation: screenIn 0.5s ease both;
}
.character-shell {
  position: relative;
  z-index: 2;
  width: min(1360px, 100%);
  height: 100%;
  margin: 0 auto;
  display: flex;
  flex-direction: column;
  gap: clamp(10px, 1.8vh, 18px);
  padding: clamp(14px, 3vh, 28px) clamp(16px, 3.4vw, 48px) clamp(12px, 2.4vh, 22px);
}
.character-steps {
  display: flex;
  align-items: center;
  justify-content: center;
  gap: 11px;
  font-family: var(--serif);
  font-size: 7px;
  letter-spacing: 0.16em;
  text-transform: uppercase;
  color: #646879;
}
.character-steps i { width: 26px; height: 1px; background: rgba(232, 199, 122, 0.2); }
.character-step.is-done { color: #8d91a0; }
.character-step.is-current { color: var(--gold-bright); }
.character-step.is-current::after { content: ' ·'; color: var(--gold); }

.character-body {
  flex: 1;
  min-height: 0;
  display: grid;
  grid-template-columns: 300px minmax(0, 1fr);
  gap: 18px;
}
.character-list {
  min-height: 0;
  display: flex;
  flex-direction: column;
  gap: 8px;
  overflow-y: auto;
  padding: 2px 4px 2px 0;
  scrollbar-width: thin;
  scrollbar-color: rgba(232, 199, 122, 0.2) transparent;
}
.character-item {
  position: relative;
  flex: none;
  display: grid;
  grid-template-columns: 54px 1fr 16px;
  align-items: center;
  gap: 10px;
  min-height: 76px;
  padding: 9px 12px 9px 9px;
  border: 1px solid rgba(232, 199, 122, 0.15);
  border-radius: 2px;
  background: linear-gradient(100deg, rgba(15, 19, 32, 0.88), rgba(9, 12, 21, 0.68));
  text-align: left;
  transition: border-color 0.25s, background 0.25s, box-shadow 0.25s;
  overflow: hidden;
}
.character-item::after {
  content: '';
  position: absolute;
  inset: 0;
  background: linear-gradient(100deg, rgba(232, 199, 122, 0.12), transparent 72%);
  opacity: 0;
  transition: opacity 0.25s;
  pointer-events: none;
}
.character-item:hover { border-color: rgba(232, 199, 122, 0.4); }
.character-item:hover::after { opacity: 0.4; }
.character-item.is-selected {
  border-color: rgba(232, 199, 122, 0.62);
  background: linear-gradient(100deg, rgba(46, 38, 23, 0.8), rgba(13, 16, 27, 0.72));
  box-shadow: 0 0 24px rgba(232, 199, 122, 0.1), inset 0 0 24px rgba(232, 199, 122, 0.04);
}
.character-item.is-selected::after { opacity: 0.8; }
.character-item__portrait {
  position: relative;
  z-index: 1;
  width: 54px;
  height: 64px;
  border: 1px solid rgba(232, 199, 122, 0.32);
  overflow: hidden;
  background: #0a0d17;
}
.character-item__portrait img {
  width: 100%;
  height: 100%;
  object-fit: cover;
  object-position: 50% 14%;
  filter: saturate(1.02);
}
.character-item__body { position: relative; z-index: 1; display: flex; flex-direction: column; gap: 1px; min-width: 0; }
.character-item__name {
  font-family: var(--serif);
  font-size: 13px;
  font-weight: 500;
  letter-spacing: 0.07em;
  color: #d9d0bd;
}
.character-item.is-selected .character-item__name { color: var(--gold-bright); }
.character-item__sub { font-size: 12px; font-style: italic; color: #777b8c; white-space: nowrap; overflow: hidden; text-overflow: ellipsis; }
.character-item__meta { font-family: var(--serif); font-size: 6.5px; letter-spacing: 0.16em; text-transform: uppercase; color: var(--gold-dim); }
.character-item__mark { position: relative; z-index: 1; font-size: 9px; color: var(--gold-dim); text-align: center; opacity: 0; transition: opacity 0.25s; }
.character-item.is-selected .character-item__mark { opacity: 1; color: var(--gold-bright); text-shadow: 0 0 12px rgba(232, 199, 122, 0.8); }
.character-list__seal {
  flex: none;
  display: flex;
  align-items: flex-start;
  gap: 10px;
  margin-top: 2px;
  padding: 12px;
  border: 1px dashed rgba(232, 199, 122, 0.16);
  border-radius: 2px;
  background: rgba(8, 11, 19, 0.35);
}
.character-list__seal span { color: var(--gold-dim); font-size: 9px; }
.character-list__seal p { margin: 0; font-size: 11.5px; font-style: italic; line-height: 1.45; color: #666a7b; }

.character-detail { min-height: 0; display: flex; }
.character-panel {
  position: relative;
  flex: 1;
  min-height: 0;
  display: flex;
  flex-direction: column;
  border: 1px solid rgba(232, 199, 122, 0.22);
  border-radius: 2px;
  background:
    radial-gradient(ellipse at 80% 0%, rgba(232, 199, 122, 0.055), transparent 50%),
    linear-gradient(158deg, rgba(13, 17, 30, 0.93), rgba(7, 9, 17, 0.9));
  box-shadow: 0 26px 70px rgba(0, 0, 0, 0.45), inset 0 1px 0 rgba(255, 255, 255, 0.03);
  overflow: hidden;
}
.character-panel::before,
.character-panel::after {
  content: '';
  position: absolute;
  width: 24px;
  height: 24px;
  border-color: rgba(232, 199, 122, 0.5);
  border-style: solid;
  pointer-events: none;
  z-index: 2;
}
.character-panel::before { top: 6px; left: 6px; border-width: 1px 0 0 1px; }
.character-panel::after { bottom: 6px; right: 6px; border-width: 0 1px 1px 0; }

.character-hero {
  flex: none;
  display: grid;
  grid-template-columns: 186px minmax(0, 1fr);
  gap: clamp(18px, 2.4vw, 30px);
  padding: 20px clamp(20px, 2.8vw, 34px) 15px;
  border-bottom: 1px solid rgba(232, 199, 122, 0.1);
  background: linear-gradient(180deg, rgba(232, 199, 122, 0.035), transparent);
}
.character-portrait { margin: 0; display: flex; flex-direction: column; gap: 7px; }
.character-portrait img {
  width: 100%;
  height: 246px;
  object-fit: cover;
  object-position: 50% 14%;
  border: 1px solid rgba(232, 199, 122, 0.38);
  box-shadow: 0 10px 34px rgba(0, 0, 0, 0.45), 0 0 28px rgba(232, 199, 122, 0.08);
  filter: saturate(1.03);
}
.character-portrait figcaption {
  font-family: var(--serif);
  font-size: 6.5px;
  letter-spacing: 0.18em;
  text-transform: uppercase;
  text-align: center;
  color: var(--gold-dim);
}
.character-identity { display: flex; flex-direction: column; min-width: 0; }
.character-name {
  margin: 6px 0 1px;
  font-family: var(--serif);
  font-weight: 400;
  font-size: clamp(30px, 3.2vw, 40px);
  line-height: 1.05;
  letter-spacing: 0.04em;
  color: #f0e5cd;
}
.character-title { margin: 0; font-family: var(--body); font-style: italic; font-size: 17px; color: var(--gold-dim); }
.character-tags { display: flex; flex-wrap: wrap; gap: 6px; margin-top: 11px; }
.character-tag {
  padding: 3px 8px;
  border: 1px solid rgba(232, 199, 122, 0.18);
  border-radius: 2px;
  font-family: var(--serif);
  font-size: 7px;
  letter-spacing: 0.14em;
  text-transform: uppercase;
  color: #8d91a1;
  background: rgba(0, 0, 0, 0.12);
}
.character-tag b { color: var(--gold); font-weight: 500; }
.character-skill {
  margin-top: auto;
  padding: 11px 14px 12px;
  border: 1px solid rgba(232, 199, 122, 0.24);
  border-radius: 2px;
  background:
    linear-gradient(100deg, rgba(232, 199, 122, 0.1), rgba(232, 199, 122, 0.02) 70%),
    rgba(5, 8, 15, 0.45);
  box-shadow: inset 0 0 24px rgba(232, 199, 122, 0.035);
}
.character-skill__kicker {
  font-family: var(--serif);
  font-size: 6.5px;
  letter-spacing: 0.22em;
  text-transform: uppercase;
  color: var(--gold-dim);
}
.character-skill__head { display: flex; align-items: center; gap: 8px; margin: 3px 0 3px; }
.character-skill__icon { font-size: 9px; color: var(--gold-bright); text-shadow: 0 0 12px rgba(232, 199, 122, 0.8); }
.character-skill h4 { margin: 0; font-family: var(--serif); font-size: 15px; font-weight: 500; letter-spacing: 0.08em; color: var(--gold-bright); }
.character-skill__tag {
  margin-left: auto;
  padding: 2px 6px;
  border: 1px solid rgba(232, 199, 122, 0.2);
  border-radius: 2px;
  font-family: var(--serif);
  font-size: 6px;
  letter-spacing: 0.16em;
  text-transform: uppercase;
  color: #8d91a1;
}
.character-skill p { margin: 0; font-size: 12.5px; font-style: italic; line-height: 1.45; color: #9a9baa; }

.character-columns {
  flex: 1;
  min-height: 0;
  display: grid;
  grid-template-columns: minmax(240px, 0.82fr) minmax(0, 1.18fr);
  gap: clamp(18px, 2.6vw, 34px);
  padding: 14px clamp(20px, 2.8vw, 34px) 12px;
}
.character-stats-block { display: flex; flex-direction: column; gap: 8px; min-width: 0; }
.character-section-label {
  font-family: var(--serif);
  font-size: 7px;
  letter-spacing: 0.24em;
  text-transform: uppercase;
  color: var(--gold-dim);
  padding-bottom: 6px;
  border-bottom: 1px solid rgba(232, 199, 122, 0.12);
}
.character-stats { display: flex; flex-direction: column; gap: 7px; }
.character-stat { display: grid; grid-template-columns: 82px minmax(0, 1fr) 26px; align-items: center; gap: 9px; }
.character-stat__label { font-family: var(--serif); font-size: 7.5px; letter-spacing: 0.13em; text-transform: uppercase; color: #8d91a0; white-space: nowrap; }
.character-stat__track {
  position: relative;
  height: 5px;
  background: rgba(232, 199, 122, 0.09);
  box-shadow: inset 0 0 0 1px rgba(232, 199, 122, 0.06);
  overflow: hidden;
}
.character-stat__track i {
  display: block;
  height: 100%;
  background: linear-gradient(90deg, rgba(179, 147, 85, 0.5), var(--gold-bright));
  box-shadow: 0 0 10px rgba(232, 199, 122, 0.35);
  transition: width 0.6s cubic-bezier(0.22, 1, 0.36, 1);
}
.character-stat b { font-family: var(--serif); font-size: 11px; font-weight: 500; text-align: right; color: #e3d8c0; }

.character-lore-block { min-height: 0; display: flex; flex-direction: column; gap: 8px; }
.character-lore {
  flex: 1;
  min-height: 0;
  overflow-y: auto;
  padding-right: 8px;
  scrollbar-width: thin;
  scrollbar-color: rgba(232, 199, 122, 0.22) transparent;
  font-size: 14px;
  line-height: 1.55;
  color: #b6b4b8;
}
.character-lore p { margin: 0 0 10px; }
.character-lore p:first-child::first-letter {
  float: left;
  padding: 4px 7px 0 0;
  font-family: var(--serif);
  font-size: 34px;
  line-height: 0.75;
  color: var(--gold);
}
.character-profile {
  flex: none;
  display: grid;
  grid-template-columns: repeat(4, minmax(0, 1fr));
  border-top: 1px solid rgba(232, 199, 122, 0.12);
  background: rgba(0, 0, 0, 0.14);
}
.character-profile div {
  display: flex;
  flex-direction: column;
  gap: 2px;
  padding: 9px clamp(12px, 1.4vw, 18px);
  border-left: 1px solid rgba(232, 199, 122, 0.1);
  min-width: 0;
}
.character-profile div:first-child { border-left: 0; }
.character-profile span { font-family: var(--serif); font-size: 6px; letter-spacing: 0.16em; text-transform: uppercase; color: #666b7d; }
.character-profile b { font-family: var(--serif); font-size: 10px; font-weight: 500; letter-spacing: 0.04em; color: #d8cdb4; white-space: nowrap; overflow: hidden; text-overflow: ellipsis; }

/* preset tab */

